// analyzer/patternMatching.ts:140
pub fn narrow_type_based_on_pattern(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    pattern: PatternAtomNode,
    is_positive_test: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    match pattern.node_type {
        ParseNodeType::PatternSequence => narrow_type_based_on_sequence_pattern(
            evaluator,
            type_,
            PatternSequenceNode::cast(pattern).unwrap(),
            is_positive_test,
            node_info,
        ),

        ParseNodeType::PatternLiteral => narrow_type_based_on_literal_pattern(
            evaluator,
            type_,
            PatternLiteralNode::cast(pattern).unwrap(),
            is_positive_test,
        ),

        ParseNodeType::PatternClass => narrow_type_based_on_class_pattern(
            evaluator,
            type_,
            PatternClassNode::cast(pattern).unwrap(),
            is_positive_test,
            node_info,
        ),

        ParseNodeType::PatternAs => narrow_type_based_on_as_pattern(
            evaluator,
            type_,
            PatternAsNode::cast(pattern).unwrap(),
            is_positive_test,
            node_info,
        ),

        ParseNodeType::PatternMapping => narrow_type_based_on_mapping_pattern(
            evaluator,
            type_,
            PatternMappingNode::cast(pattern).unwrap(),
            is_positive_test,
            node_info,
        ),

        ParseNodeType::PatternValue => narrow_type_based_on_value_pattern(
            evaluator,
            type_,
            PatternValueNode::cast(pattern).unwrap(),
            is_positive_test,
        ),

        ParseNodeType::PatternCapture => {
            // A capture captures everything, so nothing remains in the negative case.
            if is_positive_test {
                type_
            } else {
                NeverType::create_never().0
            }
        }

        ParseNodeType::Error => type_,

        _ => unreachable!("a PatternAtomNode is a pattern or an error node"),
    }
}

// analyzer/patternMatching.ts:185
pub fn check_for_unused_pattern(
    evaluator: &TypeEvaluator,
    pattern: PatternAtomNode,
    subject_type: P<Type>,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    let mut subject_type = subject_type;
    let multi_or_patterns = PatternAsNode::cast(pattern)
        .map(|as_pattern| as_pattern.d().or_patterns.borrow().clone())
        .filter(|or_patterns| or_patterns.len() > 1);

    if is_never(subject_type) {
        report_unnecessary_pattern(evaluator, pattern, subject_type);
    } else if let Some(or_patterns) = multi_or_patterns {
        // Check each of the or patterns separately.
        for or_pattern in or_patterns {
            let subject_type_match =
                narrow_type_based_on_pattern(evaluator, subject_type, or_pattern, true, node_info);

            if is_never(subject_type_match) {
                report_unnecessary_pattern(evaluator, or_pattern, subject_type);
            }

            subject_type =
                narrow_type_based_on_pattern(evaluator, subject_type, or_pattern, false, node_info);
        }
    } else {
        let subject_type_match =
            narrow_type_based_on_pattern(evaluator, subject_type, pattern, true, node_info);

        if is_never(subject_type_match) {
            report_unnecessary_pattern(evaluator, pattern, subject_type);
        }
    }
}

// analyzer/patternMatching.ts:231
pub(crate) fn narrow_type_based_on_sequence_pattern(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    pattern: PatternSequenceNode,
    is_positive_test: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let mut using_tuple_expansion = false;
    let type_ = transform_possible_recursive_type_alias(Some(type_), 0).unwrap();
    let sequence_info = get_sequence_pattern_info(evaluator, pattern, type_, node_info);
    let pattern_entries = pattern.d().entries.borrow().clone();
    let star_entry_index = pattern.d().star_entry_index.get();

    // Further narrow based on pattern entry types.
    let mut filter_entry = |entry: P<SequencePatternInfo>| -> bool {
        if entry.is_definite_no_match {
            return !is_positive_test;
        }

        let mut is_plausible_match = true;
        let mut is_definite_match = true;
        let mut narrowed_entry_types: Vec<P<Type>> = Vec::new();
        let mut unnarrowed_entry_types: Vec<P<Type>> = Vec::new();
        let mut can_narrow_tuple = entry.is_tuple.unwrap_or(false);

        // Don't attempt to narrow tuples in the negative case if the subject
        // contains indeterminate-length entries or the tuple is of indeterminate
        // length.
        if !is_positive_test {
            if entry.is_indeterminate_length.unwrap_or(false)
                || entry.is_unbounded_tuple.unwrap_or(false)
            {
                can_narrow_tuple = false;
            }

            let subtype = entry.subtype.get();
            if is_class_instance(subtype) {
                let tuple_type_args = ClassType(subtype)
                    .d()
                    .priv_
                    .borrow()
                    .tuple_type_args
                    .map(|tuple_type_args| tuple_type_args.borrow().clone());
                if let Some(tuple_type_args) = tuple_type_args {
                    let unbounded_index = tuple_type_args
                        .iter()
                        .position(|type_arg| type_arg.is_unbounded);

                    if let Some(unbounded_index) = unbounded_index {
                        // If the pattern includes a "star" entry that aligns exactly with
                        // the corresponding unbounded entry in the tuple, we can narrow
                        // the tuple type.
                        if star_entry_index != Some(unbounded_index as i32) {
                            can_narrow_tuple = false;
                        }
                    }
                }
            }
        }

        // If the subject has an indeterminate length but the pattern does not accept
        // an arbitrary number of entries or accepts at least one non-star entry,
        // we can't prove that it's a definite match.
        if entry.is_indeterminate_length.unwrap_or(false) {
            if pattern_entries.len() != 1 || star_entry_index != Some(0) {
                is_definite_match = false;
            }
        }

        let mut negative_narrowed_dims: Vec<usize> = Vec::new();
        for (index, sequence_entry) in pattern_entries.iter().enumerate() {
            let entry_type = get_type_of_pattern_sequence_entry(
                evaluator,
                pattern.0,
                entry,
                index as i32,
                pattern_entries.len() as u32,
                star_entry_index,
                true,
            );

            unnarrowed_entry_types.push(entry_type);
            let narrowed_entry_type = narrow_type_based_on_pattern(
                evaluator,
                entry_type,
                sequence_entry.0,
                is_positive_test,
                node_info,
            );

            if is_positive_test {
                if Some(index as i32) == star_entry_index {
                    let narrowed_tuple_type_args = if is_class_instance(narrowed_entry_type) {
                        let narrowed_class = ClassType(narrowed_entry_type);
                        let tuple_type_args =
                            narrowed_class.d().priv_.borrow().tuple_type_args.map(|tuple_type_args| tuple_type_args.borrow().clone());
                        tuple_type_args
                            .filter(|_| !is_unbounded_tuple_class(narrowed_class).unwrap_or(false))
                    } else {
                        None
                    };
                    if let Some(narrowed_tuple_type_args) = narrowed_tuple_type_args {
                        narrowed_entry_types
                            .extend(narrowed_tuple_type_args.iter().map(|t| t.type_));
                    } else {
                        narrowed_entry_types.push(narrowed_entry_type);
                        can_narrow_tuple = false;
                    }
                } else {
                    narrowed_entry_types.push(narrowed_entry_type);

                    if is_never(narrowed_entry_type) {
                        is_plausible_match = false;
                    }
                }
            } else {
                if entry.is_potential_no_match.unwrap_or(false) {
                    is_definite_match = false;
                }

                if !is_never(narrowed_entry_type) {
                    is_definite_match = false;

                    // Record which entries were narrowed in the negative case
                    // by storing their indexes. If more than one is narrowed,
                    // we need to perform tuple expansion to represent the
                    // resulting narrowed type.
                    negative_narrowed_dims.push(index);
                    narrowed_entry_types.push(narrowed_entry_type);
                } else {
                    narrowed_entry_types.push(entry_type);
                }

                if Some(index as i32) == star_entry_index {
                    can_narrow_tuple = false;
                }
            }
        }

        if pattern_entries.is_empty() {
            // If the pattern is an empty sequence, use the entry types.
            if !entry.entry_types.is_empty() {
                narrowed_entry_types.push(combine_types(&entry.entry_types, None));
            }

            if entry.is_potential_no_match.unwrap_or(false) {
                is_definite_match = false;
            }
        }

        if !is_positive_test {
            // If the positive case is a definite match, the negative case can
            // eliminate this subtype entirely.
            if is_definite_match {
                return false;
            }

            // Can we narrow a tuple?
            if can_narrow_tuple && !negative_narrowed_dims.is_empty() {
                let tuple_class_type = evaluator.get_built_in_type(pattern.0, "tuple");
                if is_instantiable_class(tuple_class_type) {
                    // Expand the tuple in the dimensions that were narrowed.
                    // Start with the fully-narrowed set of entries.
                    let mut expanded_entry_types: Vec<Vec<P<Type>>> = Vec::new();

                    for dim in &negative_narrowed_dims {
                        let mut new_entry_types = unnarrowed_entry_types.clone();
                        new_entry_types[*dim] = narrowed_entry_types[*dim];
                        expanded_entry_types.push(new_entry_types);
                    }

                    let expanded_tuples: Vec<P<Type>> = expanded_entry_types
                        .iter()
                        .map(|entry_types| {
                            let tuple_type_args: Vec<TupleTypeArg> = entry_types
                                .iter()
                                .map(|t| TupleTypeArg {
                                    type_: *t,
                                    is_unbounded: false,
                                    is_optional: None,
                                })
                                .collect();
                            ClassType::clone_as_instance(
                                specialize_tuple_class(
                                    ClassType(tuple_class_type),
                                    &tuple_type_args,
                                    true,
                                    false,
                                ),
                                true,
                            )
                            .0
                        })
                        .collect();
                    entry.subtype.set(combine_types(&expanded_tuples, None));

                    // Note that we're using tuple expansion in case we
                    // need to limit the number of subtypes generated.
                    using_tuple_expansion = true;
                }
            }

            return true;
        }

        if is_plausible_match {
            // If this is a tuple, we can narrow it to a specific tuple type.
            // Other sequences cannot be narrowed because we don't know if they
            // are immutable (covariant).
            if can_narrow_tuple {
                let tuple_class_type = evaluator.get_built_in_type(pattern.0, "tuple");
                if is_instantiable_class(tuple_class_type) {
                    let tuple_type_args: Vec<TupleTypeArg> = narrowed_entry_types
                        .iter()
                        .map(|t| TupleTypeArg {
                            type_: *t,
                            is_unbounded: false,
                            is_optional: None,
                        })
                        .collect();
                    entry.subtype.set(
                        ClassType::clone_as_instance(
                            specialize_tuple_class(
                                ClassType(tuple_class_type),
                                &tuple_type_args,
                                true,
                                false,
                            ),
                            true,
                        )
                        .0,
                    );
                }
            }

            // If this is a supertype of Sequence, we can narrow it to a Sequence type.
            if entry.is_potential_no_match.unwrap_or(false) && !entry.is_tuple.unwrap_or(false) {
                let sequence_type = evaluator.get_typing_type(pattern.0, "Sequence");
                if let Some(sequence_type) =
                    sequence_type.filter(|sequence_type| is_instantiable_class(*sequence_type))
                {
                    let mut type_arg_type =
                        evaluator.strip_literal_value(combine_types(&narrowed_entry_types, None));

                    // If the type is a union that contains Any or Unknown, remove the other types
                    // before wrapping it in a Sequence.
                    type_arg_type =
                        contains_any_or_unknown(type_arg_type, false).unwrap_or(type_arg_type);

                    entry.subtype.set(
                        ClassType::clone_as_instance(
                            ClassType::specialize(
                                ClassType(sequence_type),
                                Some(&[type_arg_type]),
                                None,
                                false,
                                None,
                                None,
                            ),
                            true,
                        )
                        .0,
                    );
                }
            }
        }

        is_plausible_match
    };
    let sequence_info: Vec<P<SequencePatternInfo>> = sequence_info
        .into_iter()
        .filter(|entry| filter_entry(*entry))
        .collect();

    combine_types(
        &sequence_info
            .iter()
            .map(|entry| entry.subtype.get())
            .collect::<Vec<_>>(),
        Some(&CombineTypesOptions {
            max_subtype_count: if using_tuple_expansion {
                Some(MAX_SEQUENCE_PATTERN_TUPLE_EXPANSION_SUBTYPES)
            } else {
                None
            },
            ..Default::default()
        }),
    )
}

// analyzer/patternMatching.ts:453
pub(crate) fn narrow_type_based_on_as_pattern(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    pattern: PatternAsNode,
    is_positive_test: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let mut remaining_type = type_;
    let or_patterns = pattern.d().or_patterns.borrow().clone();

    if !is_positive_test {
        for subpattern in &or_patterns {
            remaining_type = narrow_type_based_on_pattern(
                evaluator,
                remaining_type,
                *subpattern,
                false,
                node_info,
            );
        }
        return remaining_type;
    }

    let narrowed_types: Vec<P<Type>> = or_patterns
        .iter()
        .map(|subpattern| {
            let narrowed_subtype = narrow_type_based_on_pattern(
                evaluator,
                remaining_type,
                *subpattern,
                true,
                node_info,
            );
            remaining_type = narrow_type_based_on_pattern(
                evaluator,
                remaining_type,
                *subpattern,
                false,
                node_info,
            );
            narrowed_subtype
        })
        .collect();
    combine_types(&narrowed_types, None)
}

// analyzer/patternMatching.ts:495
pub(crate) fn narrow_type_based_on_mapping_pattern(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    pattern: PatternMappingNode,
    is_positive_test: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    // (nested) JavaScript `===` on two literal values: primitives by value, enum and sentinel
    // literals by identity.
    fn literal_values_strictly_equal(a: &Option<LiteralValue>, b: &Option<LiteralValue>) -> bool {
        match (a, b) {
            (None, None) => true,
            (Some(LiteralValue::Number(a)), Some(LiteralValue::Number(b))) => a == b,
            (Some(LiteralValue::Bigint(a)), Some(LiteralValue::Bigint(b))) => a == b,
            (Some(LiteralValue::Boolean(a)), Some(LiteralValue::Boolean(b))) => a == b,
            (Some(LiteralValue::String(a)), Some(LiteralValue::String(b))) => a == b,
            (Some(LiteralValue::EnumLiteral(a)), Some(LiteralValue::EnumLiteral(b))) => a == b,
            (Some(LiteralValue::SentinelLiteral(a)), Some(LiteralValue::SentinelLiteral(b))) => {
                a == b
            }
            _ => false,
        }
    }

    // (nested) `literalValue as string` on a str literal.
    fn str_literal_value(class_type: ClassType) -> Option<String> {
        match &class_type.d().priv_.borrow().literal_value {
            Some(LiteralValue::String(value)) => Some(value.clone()),
            _ => None,
        }
    }

    let type_ = transform_possible_recursive_type_alias(Some(type_), 0).unwrap();
    let pattern_entries = pattern.d().entries.borrow().clone();
    let str_class =
        |class_type: ClassType| ClassType::is_built_in(class_type, Some(&["str".to_string()]));

    if !is_positive_test {
        // Handle the case where the pattern consists only of a "**x" entry.
        if pattern_entries.len() == 1
            && pattern_entries[0].node_type == ParseNodeType::PatternMappingExpandEntry
        {
            let mapping_info = get_mapping_pattern_info(evaluator, type_, pattern.0);
            return combine_types(
                &mapping_info
                    .iter()
                    .filter(|m| !m.is_definitely_mapping)
                    .map(|m| m.subtype.get())
                    .collect::<Vec<_>>(),
                None,
            );
        }

        if pattern_entries.len() != 1
            || pattern_entries[0].node_type != ParseNodeType::PatternMappingKeyEntry
        {
            return type_;
        }

        // Handle the case where the type is a union that includes a TypedDict with
        // a field discriminated by a literal.
        let key_entry = PatternMappingKeyEntryNode::cast(pattern_entries[0]).unwrap();
        let key_pattern = key_entry.d().key_pattern.get();
        let value_pattern = key_entry.d().value_pattern.get();
        let (Some(key_pattern), Some(value_pattern)) = (
            PatternLiteralNode::cast(key_pattern),
            PatternAsNode::cast(value_pattern),
        ) else {
            return type_;
        };
        let value_or_patterns = value_pattern.d().or_patterns.borrow().clone();
        if !value_or_patterns
            .iter()
            .all(|or_pattern| or_pattern.node_type == ParseNodeType::PatternLiteral)
        {
            return type_;
        }

        let key_type = evaluator
            .get_type_of_expression(key_pattern.d().expr.get(), EvalFlags::None, None)
            .type_
            .get();

        // The key type must be a str literal.
        if !is_class_instance(key_type)
            || !str_class(ClassType(key_type))
            || ClassType(key_type)
                .d()
                .priv_
                .borrow()
                .literal_value
                .is_none()
        {
            return type_;
        }
        let key_value = str_literal_value(ClassType(key_type));

        let value_types: Vec<P<Type>> = value_or_patterns
            .iter()
            .map(|or_pattern| {
                evaluator
                    .get_type_of_expression(
                        PatternLiteralNode::cast(*or_pattern)
                            .unwrap()
                            .d()
                            .expr
                            .get(),
                        EvalFlags::None,
                        None,
                    )
                    .type_
                    .get()
            })
            .collect();

        return map_subtypes(
            type_,
            &mut |subtype| {
                if is_class_instance(subtype) && ClassType::is_typed_dict_class(ClassType(subtype))
                {
                    let typed_dict_members =
                        get_typed_dict_members_for_class(evaluator, ClassType(subtype), true);
                    let member = key_value.as_ref().and_then(|key_value| {
                        typed_dict_members
                            .known_items
                            .borrow()
                            .get(key_value)
                            .cloned()
                    });

                    if let Some(member) = member {
                        if (member.is_required || member.is_provided)
                            && is_class_instance(member.value_type)
                        {
                            let member_value_type = ClassType(member.value_type);

                            // If there's at least one literal value pattern that matches
                            // the literal type of the member, we can eliminate this type.
                            if value_types.iter().any(|value_type| {
                                is_class_instance(*value_type)
                                    && ClassType::is_same_generic_class(
                                        ClassType(*value_type),
                                        member_value_type,
                                        0,
                                    )
                                    && literal_values_strictly_equal(
                                        &ClassType(*value_type).d().priv_.borrow().literal_value,
                                        &member_value_type.d().priv_.borrow().literal_value,
                                    )
                            }) {
                                return None;
                            }
                        }
                    }
                }

                Some(subtype)
            },
            None,
        );
    }

    let mapping_info = get_mapping_pattern_info(evaluator, type_, pattern.0);

    // Further narrow based on pattern entry types.
    let filter_entry = |mapping_subtype_info: P<MappingPatternInfo>| -> bool {
        if mapping_subtype_info.is_definitely_not_mapping {
            return false;
        }

        let mut is_plausible_match = true;

        for mapping_entry in &pattern_entries {
            if mapping_subtype_info.typed_dict.get().is_some() {
                if let Some(key_entry) = PatternMappingKeyEntryNode::cast(*mapping_entry) {
                    let narrowed_key_type = narrow_type_based_on_pattern(
                        evaluator,
                        evaluator.get_built_in_object(pattern.0, "str", None),
                        key_entry.d().key_pattern.get(),
                        is_positive_test,
                        node_info,
                    );

                    if is_never(narrowed_key_type) {
                        is_plausible_match = false;
                    }

                    let value_type = map_subtypes(
                        narrowed_key_type,
                        &mut |key_subtype| {
                            if is_any_or_unknown(key_subtype) {
                                return Some(key_subtype);
                            }

                            if is_class_instance(key_subtype) && str_class(ClassType(key_subtype)) {
                                if !is_literal_type(ClassType(key_subtype)) {
                                    return Some(UnknownType::create(false).0);
                                }

                                let td_entries = get_typed_dict_members_for_class(
                                    evaluator,
                                    mapping_subtype_info.typed_dict.get().unwrap(),
                                    false,
                                );
                                let key_literal = str_literal_value(ClassType(key_subtype));
                                let value_entry = key_literal.as_ref().and_then(|key_literal| {
                                    td_entries.known_items.borrow().get(key_literal).cloned()
                                });
                                if let Some(value_entry) = value_entry {
                                    let narrowed_value_type = narrow_type_based_on_pattern(
                                        evaluator,
                                        value_entry.value_type,
                                        key_entry.d().value_pattern.get(),
                                        true,
                                        node_info,
                                    );
                                    if !is_never(narrowed_value_type) {
                                        // If this is a "NotRequired" entry that has not yet been demonstrated
                                        // to be present, we can mark it as "provided" at this point.
                                        if !value_entry.is_required
                                            && !value_entry.is_provided
                                            && is_type_same(
                                                mapping_subtype_info.subtype.get(),
                                                mapping_subtype_info.typed_dict.get().unwrap().0,
                                                &TypeSameOptions::default(),
                                                0,
                                            )
                                        {
                                            let typed_dict =
                                                mapping_subtype_info.typed_dict.get().unwrap();
                                            let mut new_narrowed_entries_map: JsMap<
                                                String,
                                                TypedDictEntry,
                                            > = typed_dict
                                                .d()
                                                .priv_
                                                .borrow()
                                                .cold().typed_dict_narrowed_entries
                                                .clone()
                                                .unwrap_or_default();
                                            new_narrowed_entries_map.insert(
                                                key_literal.clone().unwrap(),
                                                TypedDictEntry {
                                                    value_type: value_entry.value_type,
                                                    is_read_only: value_entry.is_read_only,
                                                    is_required: false,
                                                    is_provided: true,
                                                },
                                            );

                                            // Clone the TypedDict object with the new entries.
                                            let new_subtype = ClassType::clone_as_instance(
                                                ClassType::clone_for_narrowed_typed_dict_entries(
                                                    ClassType::clone_as_instantiable(
                                                        typed_dict, true,
                                                    ),
                                                    Some(new_narrowed_entries_map),
                                                ),
                                                true,
                                            );
                                            mapping_subtype_info.subtype.set(new_subtype.0);
                                            mapping_subtype_info.typed_dict.set(Some(new_subtype));
                                        }

                                        return Some(narrowed_value_type);
                                    }
                                }
                            }

                            None
                        },
                        None,
                    );

                    if is_never(value_type) {
                        is_plausible_match = false;
                    }
                }
            } else if let Some(dict_type_args) = &mapping_subtype_info.dict_type_args {
                if let Some(key_entry) = PatternMappingKeyEntryNode::cast(*mapping_entry) {
                    let narrowed_key_type = narrow_type_based_on_pattern(
                        evaluator,
                        dict_type_args.key,
                        key_entry.d().key_pattern.get(),
                        is_positive_test,
                        node_info,
                    );
                    let narrowed_value_type = narrow_type_based_on_pattern(
                        evaluator,
                        dict_type_args.value,
                        key_entry.d().value_pattern.get(),
                        is_positive_test,
                        node_info,
                    );
                    if is_never(narrowed_key_type) || is_never(narrowed_value_type) {
                        is_plausible_match = false;
                    }
                }
            }
        }

        is_plausible_match
    };
    let mapping_info: Vec<P<MappingPatternInfo>> = mapping_info
        .into_iter()
        .filter(|entry| filter_entry(*entry))
        .collect();

    combine_types(
        &mapping_info
            .iter()
            .map(|entry| entry.subtype.get())
            .collect::<Vec<_>>(),
        None,
    )
}

// analyzer/patternMatching.ts:689
pub(crate) fn get_positional_match_arg_names(
    evaluator: &TypeEvaluator,
    type_: ClassType,
) -> Vec<String> {
    let match_args_member_info =
        look_up_class_member(type_, "__match_args__", MemberAccessFlags::Default, None);
    if let Some(match_args_member_info) = match_args_member_info {
        let match_args_type = evaluator.get_type_of_member(&match_args_member_info);
        if is_class_instance(match_args_type)
            && is_tuple_class(ClassType(match_args_type))
            && !is_unbounded_tuple_class(ClassType(match_args_type)).unwrap_or(false)
        {
            let tuple_args = ClassType(match_args_type)
                .d()
                .priv_
                .borrow()
                .tuple_type_args
                .map(|tuple_type_args| tuple_type_args.borrow().clone());
            if let Some(tuple_args) = tuple_args {
                // Are all the args string literals?
                if tuple_args.iter().all(|arg| {
                    is_class_instance(arg.type_)
                        && ClassType::is_built_in(ClassType(arg.type_), Some(&["str".to_string()]))
                        && is_literal_type(ClassType(arg.type_))
                }) {
                    return tuple_args
                        .iter()
                        .map(
                            |arg| match &ClassType(arg.type_).d().priv_.borrow().literal_value {
                                Some(LiteralValue::String(value)) => value.clone(),
                                _ => unreachable!("a str literal holds a string"),
                            },
                        )
                        .collect();
                }
            }
        }
    }

    Vec::new()
}

// analyzer/patternMatching.ts:716
pub(crate) fn narrow_type_based_on_literal_pattern(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    pattern: PatternLiteralNode,
    is_positive_test: bool,
) -> P<Type> {
    let literal_type = evaluator
        .get_type_of_expression(pattern.d().expr.get(), EvalFlags::None, None)
        .type_
        .get();
    let bool_class =
        |class_type: ClassType| ClassType::is_built_in(class_type, Some(&["bool".to_string()]));

    if !is_positive_test {
        return evaluator.map_subtypes_expand_type_vars(
            type_,
            None,
            &mut |expanded_subtype, _, _| {
                if is_class_instance(literal_type)
                    && is_literal_type(ClassType(literal_type))
                    && is_class_instance(expanded_subtype)
                    && is_literal_type(ClassType(expanded_subtype))
                    && (evaluator.assign_type(
                        literal_type,
                        expanded_subtype,
                        None,
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ) || is_int_literal_pattern_equal_to_bool(
                        ClassType(literal_type),
                        ClassType(expanded_subtype),
                    ))
                {
                    return None;
                }

                if is_none_instance(expanded_subtype) && is_none_instance(literal_type) {
                    return None;
                }

                // Narrow a non-literal bool based on a literal bool pattern.
                if is_class_instance(expanded_subtype)
                    && bool_class(ClassType(expanded_subtype))
                    && ClassType(expanded_subtype)
                        .d()
                        .priv_
                        .borrow()
                        .literal_value
                        .is_none()
                    && is_class_instance(literal_type)
                    && bool_class(ClassType(literal_type))
                    && ClassType(literal_type)
                        .d()
                        .priv_
                        .borrow()
                        .literal_value
                        .is_some()
                {
                    let literal_value = ClassType(literal_type)
                        .d()
                        .priv_
                        .borrow()
                        .literal_value
                        .clone();
                    let Some(LiteralValue::Boolean(literal_bool)) = literal_value else {
                        unreachable!("a bool literal holds a boolean");
                    };
                    return Some(
                        ClassType::clone_with_literal(
                            ClassType(literal_type),
                            Some(LiteralValue::Boolean(!literal_bool)),
                        )
                        .0,
                    );
                }

                Some(expanded_subtype)
            },
            0,
        );
    }

    evaluator.map_subtypes_expand_type_vars(
        type_,
        None,
        &mut |expanded_subtype, _, _| {
            if is_class_instance(literal_type)
                && is_literal_type(ClassType(literal_type))
                && is_class_instance(expanded_subtype)
                && is_literal_type(ClassType(expanded_subtype))
                && is_int_literal_pattern_equal_to_bool(
                    ClassType(literal_type),
                    ClassType(expanded_subtype),
                )
            {
                return Some(expanded_subtype);
            }

            if evaluator.assign_type(
                expanded_subtype,
                literal_type,
                None,
                None,
                AssignTypeFlags::Default,
                0,
            ) {
                // We have to be careful here because the runtime uses an equality
                // check, but the expandedSubtype could be a superclass that is not
                // the literal type. For example, the expanded subtype might be float
                // and the literal type is Literal[3]. A value of 3.0 will match this
                // pattern, but we cannot narrow it to Literal[3] in this case.
                if !is_class_instance(literal_type)
                    || !is_literal_type(ClassType(literal_type))
                    || is_type_same(
                        evaluator.strip_literal_value(expanded_subtype),
                        evaluator.strip_literal_value(literal_type),
                        &TypeSameOptions::default(),
                        0,
                    )
                {
                    return Some(literal_type);
                }

                return Some(expanded_subtype);
            }

            // See if the subtype is a subclass of the literal's class. For example,
            // if it's a literal str, see if the subtype is subclass of str.
            if is_class_instance(literal_type) && is_class_instance(expanded_subtype) {
                if is_literal_type(ClassType(literal_type))
                    && !is_literal_type(ClassType(expanded_subtype))
                {
                    if evaluator.assign_type(
                        ClassType::clone_with_literal(ClassType(literal_type), None).0,
                        expanded_subtype,
                        None,
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        return Some(expanded_subtype);
                    }
                } else if evaluator.assign_type(
                    literal_type,
                    expanded_subtype,
                    None,
                    None,
                    AssignTypeFlags::Default,
                    0,
                ) {
                    return Some(expanded_subtype);
                }
            }
            None
        },
        0,
    )
}

// analyzer/patternMatching.ts:805
pub(crate) fn is_int_literal_pattern_equal_to_bool(
    pattern_type: ClassType,
    subject_type: ClassType,
) -> bool {
    // Numeric literal patterns use equality, so 0 and 1 also match False and True.
    // The inverse isn't true because singleton bool patterns use identity.
    if !ClassType::is_built_in(pattern_type, Some(&["int".to_string()]))
        || !ClassType::is_built_in(subject_type, Some(&["bool".to_string()]))
    {
        return false;
    }

    let pattern_value = pattern_type.d().priv_.borrow().literal_value.clone();
    let subject_value = subject_type.d().priv_.borrow().literal_value.clone();
    let is_number_or_bigint = matches!(
        pattern_value,
        Some(LiteralValue::Number(_)) | Some(LiteralValue::Bigint(_))
    );
    let Some(LiteralValue::Boolean(subject_value)) = subject_value.filter(|_| is_number_or_bigint)
    else {
        return false;
    };

    let bool_as_number: i64 = if subject_value { 1 } else { 0 };
    match pattern_value {
        Some(LiteralValue::Bigint(pattern_value)) => {
            pattern_value == JsBigInt::from(bool_as_number)
        }
        Some(LiteralValue::Number(pattern_value)) => pattern_value == bool_as_number as f64,
        _ => false,
    }
}

// analyzer/patternMatching.ts:828
pub(crate) fn specialize_bounded_match_type_params(
    evaluator: &TypeEvaluator,
    match_type: ClassType,
    solved_type_args: Option<&[P<Type>]>,
    condition: Option<&[TypeCondition]>,
) -> P<Type> {
    // `solvedTypeArgs` is indexed by `matchType`'s own type parameters, so the
    // caller must align it to the pattern class (e.g. pass `resultType.priv.typeArgs`
    // where `resultType` is the same generic class). The subject's own type arguments
    // must not be used here: the subject may be a different generic class (e.g. a
    // generic supertype), and indexing it by the pattern class's parameters would
    // misread unrelated arguments.
    let type_params = match_type.d().shared.get().type_params.borrow().clone();
    let type_args: Vec<P<Type>> = type_params
        .iter()
        .enumerate()
        .map(|(index, param)| {
            let specialized_arg =
                solved_type_args.and_then(|solved_type_args| solved_type_args.get(index).copied());

            // Keep an argument unless it is the unsolved sentinel (a bare top-level
            // Unknown left by the constraint solver when the subject carried no type
            // arguments). A concrete argument that is merely implicitly parameterized -
            // e.g. bare `list` (`list[Unknown]`) or `dict` (`dict[Unknown, Unknown]`) - is
            // a real, solved type and must be preserved rather than widened to the bound.
            // A bare in-scope TypeVar (e.g. a subject `Thing[S]` from a generic function
            // `def f[S: bool]`) is likewise a legitimately narrowed argument.
            if let Some(specialized_arg) = specialized_arg {
                if !is_unknown(specialized_arg) {
                    return specialized_arg;
                }
            }

            if is_type_var(param.0) {
                if let Some(bound_type) = param.d().shared.get().bound_type.get() {
                    return convert_to_instance(bound_type, true);
                }
            }

            specialized_arg.unwrap_or_else(|| {
                get_unknown_for_type_var(*param, evaluator.get_tuple_class_type())
            })
        })
        .collect();

    add_condition_to_type(
        convert_to_instance(
            ClassType::specialize(match_type, Some(&type_args), None, false, None, None).0,
            true,
        ),
        condition,
        None,
    )
}

// analyzer/patternMatching.ts:864
pub(crate) fn narrow_type_based_on_class_pattern(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    pattern: PatternClassNode,
    is_positive_test: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let mut expr_type = evaluator
        .get_type_of_expression(
            pattern.d().class_name.get(),
            EvalFlags::CallBaseDefaults,
            None,
        )
        .type_
        .get();

    // If this is a class (but not a type alias that refers to a class),
    // specialize it with Unknown type arguments.
    if is_class(expr_type)
        && expr_type
            .props
            .borrow()
            .as_ref()
            .is_none_or(|props| props.type_alias_info.is_none())
    {
        expr_type = ClassType::clone_remove_type_promotions(ClassType(expr_type)).0;
        expr_type = specialize_with_unknown_type_args(
            ClassType(expr_type),
            evaluator.get_tuple_class_type(),
        )
        .0;
    }

    let pattern_args = pattern.d().args.borrow().clone();
    let is_built_in = |class_type: ClassType, name: &str| {
        ClassType::is_built_in(class_type, Some(&[name.to_string()]))
    };

    // Are there any positional arguments? If so, try to get the mappings for
    // these arguments by fetching the __match_args__ symbol from the class.
    let mut positional_arg_names: Vec<String> = Vec::new();
    if pattern_args.iter().any(|arg| arg.d().name.get().is_none())
        && is_instantiable_class(expr_type)
    {
        positional_arg_names = get_positional_match_arg_names(evaluator, ClassType(expr_type));
    }

    if !is_positive_test {
        // Don't attempt to narrow if the class type is a more complex type (e.g. a TypeVar or union).
        if !is_instantiable_class(expr_type) {
            return type_;
        }

        let mut class_type = ClassType(expr_type);

        if !class_type.d().shared.get().type_params.borrow().is_empty() {
            class_type = ClassType::specialize(class_type, None, None, false, None, None);
        }

        let class_instance = ClassType::clone_as_instance(class_type, true);
        let is_pattern_metaclass = is_metaclass_instance(class_instance.0);

        let options = MapSubtypesOptions {
            expand_callback: Some(ExpandCallback::NarrowTypeBasedOnClassPattern(
                ExpandCallbackNarrowTypeBasedOnClassPattern {
                    evaluator: *evaluator.evaluator_interface.get().unwrap(),
                    pattern,
                },
            )),
            ..Default::default()
        };

        return evaluator.map_subtypes_expand_type_vars(
            type_,
            Some(&options),
            &mut |subject_subtype_expanded, subject_subtype_unexpanded, _| {
                // Handle the case where the class pattern references type() or a subtype thereof
                // and the subject type is an instantiable class itself.
                if is_pattern_metaclass && is_instantiable_class(subject_subtype_expanded) {
                    let metaclass = ClassType(subject_subtype_expanded)
                        .d()
                        .shared
                        .get()
                        .effective_metaclass
                        .get()
                        .unwrap_or_else(|| UnknownType::create(false).0);
                    if is_instantiable_class(class_type.0)
                        && evaluator.assign_type(
                            class_type.0,
                            metaclass,
                            None,
                            None,
                            AssignTypeFlags::Default,
                            0,
                        )
                    {
                        return None;
                    }

                    return Some(subject_subtype_expanded);
                }

                // Handle Callable specially.
                if !is_any_or_unknown(subject_subtype_expanded)
                    && is_instantiable_class(class_type.0)
                    && is_built_in(class_type, "Callable")
                {
                    if evaluator.assign_type(
                        get_unknown_type_for_callable().0,
                        subject_subtype_expanded,
                        None,
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        return None;
                    }
                }

                if !is_none_instance(subject_subtype_expanded)
                    && !is_class_instance(subject_subtype_expanded)
                {
                    return Some(subject_subtype_unexpanded);
                }

                // Handle NoneType specially.
                if is_none_instance(subject_subtype_expanded)
                    && is_instantiable_class(class_type.0)
                    && is_built_in(class_type, "NoneType")
                {
                    return None;
                }

                if !evaluator.assign_type(
                    class_instance.0,
                    subject_subtype_expanded,
                    None,
                    None,
                    AssignTypeFlags::Default,
                    0,
                ) {
                    return Some(subject_subtype_expanded);
                }

                // Handle literal types specially.
                if is_class_instance(subject_subtype_expanded)
                    && is_literal_type(ClassType(subject_subtype_expanded))
                {
                    return None;
                }

                if pattern_args.is_empty() {
                    if is_class(class_instance.0) && is_class(subject_subtype_expanded) {
                        // We know that this match will always succeed, so we can
                        // eliminate this subtype.
                        return None;
                    }

                    return Some(subject_subtype_expanded);
                }

                // We might be able to narrow further based on arguments, but only
                // if the types match exactly, the subject subtype is a final class (and
                // therefore cannot be subclassed), or the pattern class is a protocol
                // class.
                if !evaluator.assign_type(
                    subject_subtype_expanded,
                    class_instance.0,
                    None,
                    None,
                    AssignTypeFlags::Default,
                    0,
                ) {
                    if is_class(subject_subtype_expanded)
                        && !ClassType::is_final(ClassType(subject_subtype_expanded))
                        && !ClassType::is_protocol_class(class_instance)
                    {
                        return Some(subject_subtype_expanded);
                    }
                }

                for index in 0..pattern_args.len() {
                    let narrowed_arg_type = narrow_type_of_class_pattern_arg(
                        evaluator,
                        pattern_args[index],
                        index as i32,
                        &positional_arg_names,
                        subject_subtype_expanded,
                        is_positive_test,
                        node_info,
                    );

                    if !is_never(narrowed_arg_type) {
                        return Some(subject_subtype_unexpanded);
                    }
                }

                // We've completely eliminated the type based on the arguments.
                None
            },
            0,
        );
    }

    if !TypeBase::is_instantiable(expr_type) && !is_never(expr_type) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocAddendum::type_not_class()
                .format(&[("type", &evaluator.print_type(expr_type, None))]),
            pattern.d().class_name.get(),
            None,
        );

        return if is_positive_test {
            UnknownType::create(false).0
        } else {
            type_
        };
    } else if is_instantiable_class(expr_type) {
        if ClassType::is_protocol_class(ClassType(expr_type))
            && !ClassType::is_runtime_checkable(ClassType(expr_type))
        {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocAddendum::protocol_requires_runtime_checkable(),
                pattern.d().class_name.get(),
                None,
            );

            return if is_positive_test {
                UnknownType::create(false).0
            } else {
                type_
            };
        } else if ClassType::is_typed_dict_class(ClassType(expr_type)) {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::typed_dict_in_class_pattern(),
                pattern.d().class_name.get(),
                None,
            );

            return if is_positive_test {
                UnknownType::create(false).0
            } else {
                type_
            };
        }
    }

    evaluator.map_subtypes_expand_type_vars(
        expr_type,
        None,
        &mut |expanded_subtype, unexpanded_subtype, _| {
            if is_any_or_unknown(expanded_subtype) {
                return Some(unexpanded_subtype);
            }

            if is_instantiable_class(expanded_subtype) {
                let expanded_class = ClassType(expanded_subtype);
                let expanded_subtype_instance = convert_to_instance(expanded_subtype, true);
                let is_pattern_metaclass = is_metaclass_instance(expanded_subtype_instance);

                return Some(evaluator.map_subtypes_expand_type_vars(
                    type_,
                    None,
                    &mut |subject_subtype_expanded, _, _| {
                        if is_any_or_unknown(subject_subtype_expanded) {
                            if is_instantiable_class(expanded_subtype)
                                && is_built_in(expanded_class, "Callable")
                            {
                                // Convert to an unknown callable type.
                                let unknown_callable = FunctionType::create_synthesized_instance(
                                    "",
                                    FunctionTypeFlags::GradualCallableForm,
                                );
                                FunctionType::add_default_params(
                                    unknown_callable,
                                    is_unknown(subject_subtype_expanded),
                                );
                                unknown_callable
                                    .d()
                                    .shared
                                    .get()
                                    .declared_return_type
                                    .set(Some(subject_subtype_expanded));
                                return Some(unknown_callable.0);
                            }

                            return Some(convert_to_instance(unexpanded_subtype, true));
                        }

                        // Handle the case where the class pattern references type() or a subtype thereof
                        // and the subject type is a class itself.
                        if is_pattern_metaclass && is_instantiable_class(subject_subtype_expanded) {
                            let metaclass = ClassType(subject_subtype_expanded)
                                .d()
                                .shared
                                .get()
                                .effective_metaclass
                                .get()
                                .unwrap_or_else(|| UnknownType::create(false).0);
                            if evaluator.assign_type(
                                expanded_subtype,
                                metaclass,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) || evaluator.assign_type(
                                metaclass,
                                expanded_subtype,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) {
                                return Some(subject_subtype_expanded);
                            }

                            return None;
                        }

                        // Handle NoneType specially.
                        if is_none_instance(subject_subtype_expanded)
                            && is_instantiable_class(expanded_subtype)
                            && is_built_in(expanded_class, "NoneType")
                        {
                            return Some(subject_subtype_expanded);
                        }

                        // Handle Callable specially.
                        if is_instantiable_class(expanded_subtype)
                            && is_built_in(expanded_class, "Callable")
                        {
                            let callable_type = get_unknown_type_for_callable().0;

                            if evaluator.assign_type(
                                callable_type,
                                subject_subtype_expanded,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) {
                                return Some(subject_subtype_expanded);
                            }

                            let subj_obj_type = convert_to_instance(subject_subtype_expanded, true);
                            if evaluator.assign_type(
                                subj_obj_type,
                                callable_type,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) {
                                return Some(callable_type);
                            }

                            return None;
                        }

                        if is_class_instance(subject_subtype_expanded) {
                            let mut result_type: P<Type>;

                            if evaluator.assign_type(
                                ClassType::clone_as_instance(expanded_class, true).0,
                                subject_subtype_expanded,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) {
                                result_type = subject_subtype_expanded;
                            } else if evaluator.assign_type(
                                subject_subtype_expanded,
                                ClassType::clone_as_instance(expanded_class, true).0,
                                None,
                                None,
                                AssignTypeFlags::Default,
                                0,
                            ) {
                                result_type = add_condition_to_type(
                                    convert_to_instance(unexpanded_subtype, true),
                                    get_type_condition(subject_subtype_expanded).as_deref(),
                                    None,
                                );

                                // Try to retain the type arguments for the pattern class type.
                                if is_instantiable_class(unexpanded_subtype)
                                    && is_class_instance(subject_subtype_expanded)
                                {
                                    let unexpanded_class = ClassType(unexpanded_subtype);
                                    if ClassType::is_special_built_in(unexpanded_class, None)
                                        || !unexpanded_class
                                            .d()
                                            .shared
                                            .get()
                                            .type_params
                                            .borrow()
                                            .is_empty()
                                    {
                                        let constraints = ConstraintTracker::new();
                                        let unspecialized_match_type = ClassType::specialize(
                                            unexpanded_class,
                                            None,
                                            None,
                                            false,
                                            None,
                                            None,
                                        );

                                        let match_type_instance = ClassType::clone_as_instance(
                                            unspecialized_match_type,
                                            true,
                                        );
                                        if add_constraints_for_expected_type(
                                            evaluator,
                                            match_type_instance,
                                            subject_subtype_expanded,
                                            constraints,
                                            None,
                                            None,
                                        ) {
                                            result_type = evaluator.solve_and_apply_constraints(
                                                match_type_instance.0,
                                                constraints,
                                                Some(&ApplyTypeVarOptions {
                                                    replace_unsolved: Some(
                                                        ApplyTypeVarOptionsReplaceUnsolved {
                                                            scope_ids: get_type_var_scope_ids(
                                                                unexpanded_subtype,
                                                            ),
                                                            tuple_class_type: evaluator
                                                                .get_tuple_class_type(),
                                                            unsolved_exempt_type_vars: None,
                                                            use_unknown: None,
                                                            eliminate_unsolved_in_unions: None,
                                                        },
                                                    ),
                                                    ..Default::default()
                                                }),
                                                None,
                                            );
                                        }
                                    }
                                }
                            } else {
                                return None;
                            }

                            // For a generic class pattern whose type parameters are bounded
                            // (e.g. `class Thing[T: bool]`), the subject may carry no type arguments,
                            // leaving the parameters unsolved. Fall back to each parameter's bound -
                            // but only for the pattern class itself. When the subject narrowed to a
                            // proper subclass of the pattern class, its own type arguments must be
                            // preserved rather than rebuilt from the (widened) base.
                            if is_class_instance(result_type)
                                && is_instantiable_class(unexpanded_subtype)
                                && ClassType::is_same_generic_class(
                                    ClassType(result_type),
                                    ClassType::clone_as_instance(
                                        ClassType(unexpanded_subtype),
                                        true,
                                    ),
                                    0,
                                )
                                && ClassType(unexpanded_subtype)
                                    .d()
                                    .shared
                                    .get()
                                    .type_params
                                    .borrow()
                                    .iter()
                                    .any(|param| {
                                        is_type_var(param.0)
                                            && param.d().shared.get().bound_type.get().is_some()
                                    })
                            {
                                let result_type_args =
                                    ClassType(result_type).d().priv_.borrow().type_args.clone();
                                result_type = specialize_bounded_match_type_params(
                                    evaluator,
                                    ClassType(unexpanded_subtype),
                                    result_type_args.as_deref(),
                                    get_type_condition(subject_subtype_expanded).as_deref(),
                                );
                            }

                            // Are there any positional arguments? If so, try to get the mappings for
                            // these arguments by fetching the __match_args__ symbol from the class.
                            let mut positional_arg_names: Vec<String> = Vec::new();
                            if pattern_args.iter().any(|arg| arg.d().name.get().is_none()) {
                                positional_arg_names =
                                    get_positional_match_arg_names(evaluator, expanded_class);
                            }

                            let mut is_match_valid = true;
                            for (index, arg) in pattern_args.iter().enumerate() {
                                // Narrow the arg pattern. It's possible that the actual type of the object
                                // being matched is a subtype of the resultType, so it might contain additional
                                // attributes that we don't know about.
                                let narrowed_arg_type = narrow_type_of_class_pattern_arg(
                                    evaluator,
                                    *arg,
                                    index as i32,
                                    &positional_arg_names,
                                    result_type,
                                    is_positive_test,
                                    node_info,
                                );

                                if is_never(narrowed_arg_type) {
                                    is_match_valid = false;
                                }
                            }

                            if is_match_valid {
                                return Some(result_type);
                            }
                        }

                        None
                    },
                    0,
                ));
            }

            None
        },
        0,
    )
}

// analyzer/patternMatching.ts:1214
pub(crate) fn is_class_special_case_for_class_pattern(class_type: ClassType) -> bool {
    let is_special_case_name = |full_name: &str| {
        CLASS_PATTERN_SPECIAL_CASES
            .with(|cases| cases.iter().any(|class_name| class_name == full_name))
    };

    if is_special_case_name(&class_type.d().shared.get().full_name) {
        return true;
    }

    // If the class supplies its own `__match_args__`, it's not a special case.
    let match_args_member_info = look_up_class_member(
        class_type,
        "__match_args__",
        MemberAccessFlags::Default,
        None,
    );
    if match_args_member_info.is_some() {
        return false;
    }

    // If the class derives from a built-in class, it is considered a special case.
    let mro = class_type.d().shared.get().mro.borrow().clone();
    for mro_class in mro {
        if is_class(mro_class)
            && is_special_case_name(&ClassType(mro_class).d().shared.get().full_name)
        {
            return true;
        }
    }

    false
}

// analyzer/patternMatching.ts:1236
pub(crate) fn narrow_type_of_class_pattern_arg(
    evaluator: &TypeEvaluator,
    arg: PatternClassArgumentNode,
    arg_index: i32,
    positional_arg_names: &[String],
    match_type: P<Type>,
    is_positive_test: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    let mut arg_name: Option<String> = None;

    if let Some(name) = arg.d().name.get() {
        arg_name = Some(name.d().value.clone());
    } else if (arg_index as usize) < positional_arg_names.len() {
        arg_name = Some(positional_arg_names[arg_index as usize].clone());
    }

    if is_any_or_unknown(match_type) {
        return match_type;
    }

    if !is_class(match_type) {
        return UnknownType::create(false).0;
    }

    let match_class = ClassType(match_type);

    // According to PEP 634, some built-in types use themselves as the subject
    // for the first positional argument to a class pattern. Although the PEP does
    // state so explicitly, this is true of subclasses of these built-in classes
    // if the subclass doesn't define its own __match_args__.
    let mut use_self_for_pattern = false;
    let mut self_for_pattern_type = match_class;

    if arg.d().name.get().is_none() && is_class(match_type) && arg_index == 0 {
        if is_class_special_case_for_class_pattern(match_class) {
            use_self_for_pattern = true;
        } else if positional_arg_names.is_empty() {
            let mro = match_class.d().shared.get().mro.borrow().clone();
            for mro_class in mro {
                if is_class(mro_class)
                    && is_class_special_case_for_class_pattern(ClassType(mro_class))
                {
                    self_for_pattern_type = ClassType(mro_class);
                    use_self_for_pattern = true;
                }
            }
        }
    }

    let mut arg_type: Option<P<Type>> = None;

    if use_self_for_pattern {
        arg_type = Some(ClassType::clone_as_instance(self_for_pattern_type, true).0);
    } else {
        if let Some(arg_name) = arg_name.as_deref().filter(|arg_name| !arg_name.is_empty()) {
            // TypeScript casts the PatternClassArgumentNode to an ExpressionNode here.
            arg_type = evaluator
                .use_speculative_mode(
                    Some(arg.0),
                    &mut || {
                        evaluator.get_type_of_bound_member(
                            Some(arg.0),
                            ClassType::clone_as_instance(match_class, true),
                            arg_name,
                            &EvaluatorUsage {
                                method: "get".to_string(),
                                set_type: None,
                                set_error_node: None,
                                set_expected_type_diag: None,
                            },
                            None,
                            MemberAccessFlags::Default,
                            None,
                            0,
                        )
                    },
                    None,
                )
                .map(|type_result| type_result.type_.get());
        }

        if arg_type.is_none() {
            if !is_positive_test {
                return match_type;
            }

            // If the class type in question is "final", we know that no additional
            // attributes can be added by subtypes, so it's safe to eliminate this
            // type entirely.
            if ClassType::is_final(match_class) {
                return NeverType::create_never().0;
            }

            arg_type = Some(UnknownType::create(false).0);
        }
    }

    narrow_type_based_on_pattern(
        evaluator,
        arg_type.unwrap(),
        arg.d().pattern.get().0,
        is_positive_test,
        node_info,
    )
}

// analyzer/patternMatching.ts:1317
pub(crate) fn narrow_type_based_on_value_pattern(
    evaluator: &TypeEvaluator,
    subject_type: P<Type>,
    pattern: PatternValueNode,
    is_positive_test: bool,
) -> P<Type> {
    let value_expr = pattern.d().expr.get();
    let value_type = evaluator
        .get_type_of_expression(value_expr.0, EvalFlags::None, None)
        .type_
        .get();
    let mut narrowed_subtypes: Vec<P<Type>> = Vec::new();

    evaluator.map_subtypes_expand_type_vars(
        value_type,
        None,
        &mut |value_subtype_expanded, value_subtype_unexpanded, _| {
            let options = MapSubtypesOptions {
                condition_filter: get_type_condition(value_subtype_expanded),
                ..Default::default()
            };
            narrowed_subtypes.push(evaluator.map_subtypes_expand_type_vars(
                subject_type,
                Some(&options),
                &mut |subject_subtype_expanded, _, _| {
                    // If this is a negative test, see if it's an enum value.
                    if !is_positive_test {
                        if is_class_instance(subject_subtype_expanded)
                            && is_class_instance(value_subtype_expanded)
                            && is_same_without_literal_value(
                                subject_subtype_expanded,
                                value_subtype_expanded,
                            )
                        {
                            if !is_literal_type(ClassType(subject_subtype_expanded))
                                && is_literal_type(ClassType(value_subtype_expanded))
                            {
                                let expanded_literals = enumerate_literals_for_type(
                                    evaluator,
                                    ClassType(subject_subtype_expanded),
                                );
                                if let Some(expanded_literals) = expanded_literals {
                                    return Some(combine_types(
                                        &expanded_literals
                                            .iter()
                                            .filter(|enum_type| {
                                                !ClassType::is_literal_value_same(
                                                    ClassType(value_subtype_expanded),
                                                    **enum_type,
                                                )
                                            })
                                            .map(|enum_type| enum_type.0)
                                            .collect::<Vec<_>>(),
                                        None,
                                    ));
                                }
                            }

                            if is_literal_type(ClassType(subject_subtype_expanded))
                                && ClassType::is_literal_value_same(
                                    ClassType(value_subtype_expanded),
                                    ClassType(subject_subtype_expanded),
                                )
                            {
                                return None;
                            }
                        }

                        return Some(subject_subtype_expanded);
                    }

                    if is_never(value_subtype_expanded) || is_never(subject_subtype_expanded) {
                        return Some(NeverType::create_never().0);
                    }

                    if is_any_or_unknown(value_subtype_expanded)
                        || is_any_or_unknown(subject_subtype_expanded)
                    {
                        // If either type is "Unknown" (versus Any), propagate the Unknown.
                        return Some(
                            if is_unknown(value_subtype_expanded)
                                || is_unknown(subject_subtype_expanded)
                            {
                                preserve_unknown(value_subtype_expanded, subject_subtype_expanded)
                            } else {
                                AnyType::create(false).0
                            },
                        );
                    }

                    // If both types are literals, we can compare the literal values directly.
                    if is_class_instance(subject_subtype_expanded)
                        && is_literal_type(ClassType(subject_subtype_expanded))
                        && is_class_instance(value_subtype_expanded)
                        && is_literal_type(ClassType(value_subtype_expanded))
                    {
                        return if is_same_without_literal_value(
                            subject_subtype_expanded,
                            value_subtype_expanded,
                        ) && ClassType::is_literal_value_same(
                            ClassType(value_subtype_expanded),
                            ClassType(subject_subtype_expanded),
                        ) {
                            Some(value_subtype_unexpanded)
                        } else {
                            None
                        };
                    }

                    // Determine if assignment is supported for this combination of
                    // value subtype and matching subtype.
                    let return_type = evaluator.use_speculative_mode(
                        Some(value_expr.0),
                        &mut || {
                            evaluator.get_type_of_magic_method_call(
                                value_subtype_expanded,
                                "__eq__",
                                &[P::new_eval(TypeResult::new(subject_subtype_expanded))],
                                value_expr.0,
                                None,
                                None,
                            )
                        },
                        None,
                    );

                    if return_type.is_some() {
                        Some(value_subtype_unexpanded)
                    } else {
                        None
                    }
                },
                0,
            ));

            None
        },
        0,
    );

    combine_types(&narrowed_subtypes, None)
}

// analyzer/patternMatching.ts:1418
pub(crate) fn get_mapping_pattern_info(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    node: PatternAtomNode,
) -> Vec<P<MappingPatternInfo>> {
    let mut mapping_info: Vec<P<MappingPatternInfo>> = Vec::new();
    let new_info = |subtype: P<Type>,
                    is_definitely_mapping: bool,
                    is_definitely_not_mapping: bool,
                    typed_dict: Option<ClassType>,
                    dict_type_args: Option<MappingPatternInfoDictTypeArgs>| {
        P::new_eval(MappingPatternInfo {
            subtype: Cell::new(subtype),
            is_definitely_mapping,
            is_definitely_not_mapping,
            typed_dict: Cell::new(typed_dict),
            dict_type_args,
        })
    };

    do_for_each_subtype(
        type_,
        &mut |subtype, _, _| {
            let concrete_subtype =
                evaluator.make_top_level_type_vars_concrete(subtype, false, None);

            if is_any_or_unknown(concrete_subtype) {
                mapping_info.push(new_info(
                    subtype,
                    false,
                    false,
                    None,
                    Some(MappingPatternInfoDictTypeArgs {
                        key: concrete_subtype,
                        value: concrete_subtype,
                    }),
                ));
                return;
            }

            if is_class_instance(concrete_subtype) {
                let concrete_class = ClassType(concrete_subtype);

                // Is it a TypedDict?
                if ClassType::is_typed_dict_class(concrete_class) {
                    mapping_info.push(new_info(subtype, true, false, Some(concrete_class), None));
                    return;
                }

                let mapping_type = evaluator.get_typing_type(node, "Mapping");
                let Some(mapping_type) =
                    mapping_type.filter(|mapping_type| is_instantiable_class(*mapping_type))
                else {
                    return;
                };
                let mapping_object = ClassType::clone_as_instance(ClassType(mapping_type), true);

                // Is it a subtype of Mapping?
                let constraints = ConstraintTracker::new();
                if evaluator.assign_type(
                    mapping_object.0,
                    subtype,
                    None,
                    Some(constraints),
                    AssignTypeFlags::Default,
                    0,
                ) {
                    let specialized_mapping = evaluator.solve_and_apply_constraints(
                        mapping_object.0,
                        constraints,
                        None,
                        None,
                    );
                    let type_args =
                        ClassType::cast(specialized_mapping).and_then(|specialized_mapping| {
                            specialized_mapping.d().priv_.borrow().type_args.clone()
                        });

                    if let Some(type_args) = type_args.filter(|type_args| type_args.len() >= 2) {
                        mapping_info.push(new_info(
                            subtype,
                            true,
                            false,
                            None,
                            Some(MappingPatternInfoDictTypeArgs {
                                key: type_args[0],
                                value: type_args[1],
                            }),
                        ));
                    }

                    return;
                }

                // Is it a superclass of Mapping?
                if evaluator.assign_type(
                    subtype,
                    mapping_object.0,
                    None,
                    None,
                    AssignTypeFlags::Default,
                    0,
                ) {
                    mapping_info.push(new_info(
                        subtype,
                        false,
                        false,
                        None,
                        Some(MappingPatternInfoDictTypeArgs {
                            key: UnknownType::create(false).0,
                            value: UnknownType::create(false).0,
                        }),
                    ));
                    return;
                }

                mapping_info.push(new_info(subtype, false, true, None, None));
            }
        },
        false,
    );

    mapping_info
}

// analyzer/patternMatching.ts:1503
pub(crate) fn get_sequence_pattern_info(
    evaluator: &TypeEvaluator,
    pattern: PatternSequenceNode,
    type_: P<Type>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> Vec<P<SequencePatternInfo>> {
    let pattern_entries = pattern.d().entries.borrow().clone();
    let pattern_entry_count = pattern_entries.len();
    let pattern_star_entry_index = pattern.d().star_entry_index.get();
    let mut sequence_info: Vec<P<SequencePatternInfo>> = Vec::new();
    let new_info = |subtype: P<Type>,
                    entry_types: Vec<P<Type>>,
                    is_indeterminate_length: Option<bool>,
                    is_tuple: Option<bool>,
                    is_unbounded_tuple: Option<bool>,
                    is_definite_no_match: bool,
                    is_potential_no_match: Option<bool>| {
        P::new_eval(SequencePatternInfo {
            subtype: Cell::new(subtype),
            is_definite_no_match,
            is_potential_no_match,
            entry_types,
            is_indeterminate_length,
            is_tuple,
            is_unbounded_tuple,
        })
    };
    let is_built_in = |class_type: ClassType, name: &str| {
        ClassType::is_built_in(class_type, Some(&[name.to_string()]))
    };
    let is_indeterminate_entry = |t: &TupleTypeArg| {
        t.is_unbounded || is_unpacked_type_var_tuple(t.type_) || is_unpacked_type_var(t.type_)
    };

    do_for_each_subtype(
        type_,
        &mut |subtype, _, _| {
            let concrete_subtype =
                evaluator.make_top_level_type_vars_concrete(subtype, false, None);
            let mut mro_class_to_specialize: Option<ClassType> = None;

            if is_class_instance(concrete_subtype) {
                let concrete_class = ClassType(concrete_subtype);
                let mro = concrete_class.d().shared.get().mro.borrow().clone();
                for mro_class in mro {
                    if !is_instantiable_class(mro_class) {
                        break;
                    }
                    let mro_class = ClassType(mro_class);

                    // Strings, bytes, and bytearray are explicitly excluded.
                    if is_built_in(mro_class, "str")
                        || is_built_in(mro_class, "bytes")
                        || is_built_in(mro_class, "bytearray")
                    {
                        // This is definitely not a match.
                        sequence_info.push(new_info(
                            subtype,
                            Vec::new(),
                            Some(true),
                            None,
                            None,
                            true,
                            None,
                        ));
                        return;
                    }

                    if is_built_in(mro_class, "Sequence") {
                        mro_class_to_specialize = Some(mro_class);
                        break;
                    }

                    if is_tuple_class(mro_class) {
                        mro_class_to_specialize = Some(mro_class);
                        break;
                    }
                }

                if let Some(mro_class_to_specialize) = mro_class_to_specialize {
                    let specialized_sequence = ClassType(partially_specialize_type(
                        mro_class_to_specialize.0,
                        concrete_class,
                        evaluator.get_type_class_type(),
                        None,
                    ));

                    if is_tuple_class(specialized_sequence) {
                        // The splices below edit `specializedSequence.priv.tupleTypeArgs` in place, so
                        // they reach every clone that shares the array.
                        let type_args = specialized_sequence
                            .d()
                            .priv_
                            .borrow()
                            .tuple_type_args
                            .unwrap_or_else(|| {
                                P::new_eval(std::cell::RefCell::new(vec![TupleTypeArg {
                                    type_: UnknownType::create(false).0,
                                    is_unbounded: true,
                                    is_optional: None,
                                }]))
                            });

                        let mut tuple_indeterminate_index: i32 = type_args
                            .borrow()
                            .iter()
                            .position(is_indeterminate_entry)
                            .map_or(-1, |index| index as i32);

                        let mut tuple_determinate_entry_count = type_args.borrow().len() as i32;

                        // If the tuple contains an indeterminate entry, expand or remove that
                        // entry to match the length of the pattern if possible.
                        let mut expanded_indeterminate = false;
                        // Tracks whether the indeterminate entry was spliced out to contract the tuple
                        // to fit a shorter pattern. This preserves "potential match" semantics after
                        // the splice resets tupleIndeterminateIndex to -1.
                        let mut removed_indeterminate = false;
                        if tuple_indeterminate_index >= 0 {
                            tuple_determinate_entry_count -= 1;

                            while type_args.borrow().len() < pattern_entry_count {
                                let index = tuple_indeterminate_index as usize;
                                let entry = type_args.borrow()[index].clone();
                                type_args.borrow_mut().insert(index, entry);
                                tuple_determinate_entry_count += 1;
                                tuple_indeterminate_index += 1;
                                expanded_indeterminate = true;
                            }

                            if type_args.borrow().len() > pattern_entry_count
                                && pattern_star_entry_index.is_none()
                            {
                                type_args.borrow_mut().remove(tuple_indeterminate_index as usize);
                                tuple_indeterminate_index = -1;
                                removed_indeterminate = true;
                            }
                        }

                        // If the pattern contains a star entry and there are too many entries
                        // in the tuple, we can collapse some of them into the star entry.
                        if let Some(star_entry_index) = pattern_star_entry_index {
                            if type_args.borrow().len() >= 2 && type_args.borrow().len() > pattern_entry_count {
                                let star = star_entry_index as usize;
                                let entries_to_combine = type_args.borrow().len() - pattern_entry_count + 1;
                                let removed_entries: Vec<TupleTypeArg> =
                                    type_args.borrow_mut().drain(star..star + entries_to_combine).collect();
                                type_args.borrow_mut().insert(
                                    star,
                                    TupleTypeArg {
                                        type_: combine_types(
                                            &removed_entries
                                                .iter()
                                                .map(|t| t.type_)
                                                .collect::<Vec<_>>(),
                                            None,
                                        ),
                                        is_unbounded: removed_entries
                                            .iter()
                                            .all(is_indeterminate_entry),
                                        is_optional: None,
                                    },
                                );

                                tuple_determinate_entry_count -= entries_to_combine as i32;
                                if !type_args.borrow()[star].is_unbounded {
                                    tuple_determinate_entry_count += 1;
                                }

                                // If the collapsed range included the tupleIndeterminateIndex, adjust
                                // it to reflect the new collapsed entry.
                                if tuple_indeterminate_index >= star_entry_index
                                    && tuple_indeterminate_index
                                        < star_entry_index + entries_to_combine as i32
                                {
                                    tuple_indeterminate_index = star_entry_index;
                                }
                            }
                        }

                        if type_args.borrow().len() == pattern_entry_count {
                            let mut is_definite_no_match = false;
                            let mut is_potential_no_match =
                                tuple_indeterminate_index >= 0 || removed_indeterminate;

                            // If we removed an unbounded entry to make the lengths match,
                            // this is a potential match (not definite) because the original
                            // tuple could have different lengths.
                            if removed_indeterminate {
                                is_potential_no_match = true;
                            }

                            // If the pattern includes a "star entry" and the tuple includes an
                            // indeterminate-length entry that aligns to the star entry, we can
                            // assume it will always match.
                            if !expanded_indeterminate
                                && pattern_star_entry_index.is_some()
                                && tuple_indeterminate_index >= 0
                                && pattern.d().entries.borrow().len() as i32 - 1
                                    == tuple_determinate_entry_count
                                && pattern_star_entry_index == Some(tuple_indeterminate_index)
                            {
                                is_potential_no_match = false;
                            }

                            for i in 0..pattern_entry_count {
                                let sub_pattern = pattern_entries[i];
                                let type_arg = type_args.borrow()[i].type_;
                                let narrowed_type = narrow_type_based_on_pattern(
                                    evaluator,
                                    type_arg,
                                    sub_pattern.0,
                                    true,
                                    node_info,
                                );

                                if is_never(narrowed_type) {
                                    is_definite_no_match = true;
                                }
                            }

                            sequence_info.push(new_info(
                                subtype,
                                if is_definite_no_match {
                                    Vec::new()
                                } else {
                                    type_args.borrow().iter().map(|t| t.type_).collect()
                                },
                                Some(false),
                                Some(true),
                                Some(removed_indeterminate || tuple_indeterminate_index >= 0),
                                is_definite_no_match,
                                Some(is_potential_no_match),
                            ));
                            return;
                        }

                        // If the pattern contains a star entry and the pattern associated with
                        // the star entry is unbounded, we can remove it completely under the
                        // assumption that the star pattern will capture nothing.
                        if let Some(star_entry_index) = pattern_star_entry_index {
                            let star = star_entry_index as usize;
                            let mut try_match_star_sequence = false;

                            if type_args.borrow().len() + 1 == pattern_entry_count {
                                try_match_star_sequence = true;
                                type_args.borrow_mut().insert(
                                    star,
                                    TupleTypeArg {
                                        type_: AnyType::create(false).0,
                                        is_unbounded: true,
                                        is_optional: None,
                                    },
                                );
                            } else if type_args.borrow().len() == pattern_entry_count
                                && type_args.borrow()[star].is_unbounded
                            {
                                try_match_star_sequence = true;
                            }

                            if try_match_star_sequence {
                                let mut is_definite_no_match = false;

                                for i in 0..pattern_entry_count {
                                    if i == star {
                                        continue;
                                    }

                                    let sub_pattern = pattern_entries[i];
                                    let type_arg = type_args.borrow()[i].type_;
                                    let narrowed_type = narrow_type_based_on_pattern(
                                        evaluator,
                                        type_arg,
                                        sub_pattern.0,
                                        true,
                                        node_info,
                                    );

                                    if is_never(narrowed_type) {
                                        is_definite_no_match = true;
                                    }
                                }

                                sequence_info.push(new_info(
                                    subtype,
                                    if is_definite_no_match {
                                        Vec::new()
                                    } else {
                                        type_args.borrow().iter().map(|t| t.type_).collect()
                                    },
                                    Some(false),
                                    Some(true),
                                    Some(tuple_indeterminate_index >= 0),
                                    is_definite_no_match,
                                    None,
                                ));
                                return;
                            }
                        }
                    } else {
                        let type_args = specialized_sequence.d().priv_.borrow().type_args.clone();
                        sequence_info.push(new_info(
                            subtype,
                            vec![
                                type_args
                                    .filter(|type_args| !type_args.is_empty())
                                    .map(|type_args| type_args[0])
                                    .unwrap_or_else(|| UnknownType::create(false).0),
                            ],
                            Some(true),
                            None,
                            None,
                            false,
                            None,
                        ));
                        return;
                    }
                }
            }

            if mro_class_to_specialize.is_none() {
                let sequence_type = evaluator.get_typing_type(pattern.0, "Sequence");

                if let Some(sequence_type) =
                    sequence_type.filter(|sequence_type| is_instantiable_class(*sequence_type))
                {
                    let sequence_class = ClassType(sequence_type);
                    let sequence_object = ClassType::clone_as_instance(sequence_class, true);

                    // Is it a subtype of Sequence?
                    let constraints = ConstraintTracker::new();
                    if evaluator.assign_type(
                        sequence_object.0,
                        subtype,
                        None,
                        Some(constraints),
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        let specialized_sequence = evaluator.solve_and_apply_constraints(
                            sequence_object.0,
                            constraints,
                            None,
                            None,
                        );
                        let type_args = ClassType::cast(specialized_sequence).and_then(
                            |specialized_sequence| {
                                specialized_sequence.d().priv_.borrow().type_args.clone()
                            },
                        );

                        if let Some(type_args) = type_args.filter(|type_args| !type_args.is_empty())
                        {
                            sequence_info.push(new_info(
                                subtype,
                                vec![type_args[0]],
                                Some(true),
                                None,
                                None,
                                false,
                                Some(false),
                            ));
                            return;
                        }
                    }

                    // If it wasn't a subtype of Sequence, see if it's a supertype.
                    let sequence_constraints = ConstraintTracker::new();
                    if add_constraints_for_expected_type(
                        evaluator,
                        ClassType::clone_as_instance(sequence_class, true),
                        subtype,
                        sequence_constraints,
                        Some(&get_type_var_scopes_for_node(pattern.0, node_info.reader())),
                        Some(pattern.start.get()),
                    ) {
                        let specialized_sequence = evaluator.solve_and_apply_constraints(
                            ClassType::clone_as_instantiable(sequence_class, true).0,
                            sequence_constraints,
                            None,
                            None,
                        );
                        let type_args = ClassType::cast(specialized_sequence).and_then(
                            |specialized_sequence| {
                                specialized_sequence.d().priv_.borrow().type_args.clone()
                            },
                        );

                        if let Some(type_args) = type_args.filter(|type_args| !type_args.is_empty())
                        {
                            sequence_info.push(new_info(
                                subtype,
                                vec![type_args[0]],
                                Some(true),
                                None,
                                None,
                                false,
                                Some(true),
                            ));
                            return;
                        }
                    }

                    if evaluator.assign_type(
                        subtype,
                        ClassType::specialize(
                            ClassType::clone_as_instance(sequence_class, true),
                            Some(&[UnknownType::create(false).0]),
                            None,
                            false,
                            None,
                            None,
                        )
                        .0,
                        None,
                        None,
                        AssignTypeFlags::Default,
                        0,
                    ) {
                        sequence_info.push(new_info(
                            subtype,
                            vec![UnknownType::create(false).0],
                            Some(true),
                            None,
                            None,
                            false,
                            Some(true),
                        ));
                        return;
                    }
                }
            }

            // Push an entry that indicates that this is definitely not a match.
            sequence_info.push(new_info(
                subtype,
                Vec::new(),
                Some(true),
                None,
                None,
                true,
                None,
            ));
        },
        false,
    );

    sequence_info
}

// analyzer/patternMatching.ts:1830
pub(crate) fn get_type_of_pattern_sequence_entry(
    evaluator: &TypeEvaluator,
    node: P<ParseNode>,
    sequence_info: P<SequencePatternInfo>,
    entry_index: i32,
    entry_count: u32,
    star_entry_index: Option<i32>,
    unpack_star_entry: bool,
) -> P<Type> {
    if sequence_info.is_indeterminate_length.unwrap_or(false) {
        let mut entry_type = sequence_info.entry_types[0];

        if !unpack_star_entry && Some(entry_index) == star_entry_index && !is_never(entry_type) {
            entry_type = wrap_type_in_list(evaluator, node, entry_type);
        }

        return entry_type;
    }

    let Some(star_entry_index) =
        star_entry_index.filter(|star_entry_index| entry_index >= *star_entry_index)
    else {
        return sequence_info.entry_types[entry_index as usize];
    };

    if entry_index == star_entry_index {
        // Create a list out of the entries that map to the star entry.
        // Note that we strip literal types here.
        // `Array.prototype.slice` bounds: a negative end counts from the end; both clamp to the length.
        let entry_types_len = sequence_info.entry_types.len() as i64;
        let slice_bound = |bound: i64| {
            if bound < 0 {
                (entry_types_len + bound).max(0)
            } else {
                bound.min(entry_types_len)
            }
        };
        let start = slice_bound(star_entry_index as i64) as usize;
        let end = slice_bound(star_entry_index as i64 + entry_types_len - entry_count as i64 + 1)
            as usize;
        let star_entry_types: Vec<P<Type>> = sequence_info.entry_types[start..end.max(start)]
            .iter()
            .map(|type_| {
                // If this is a TypeVarTuple, there's not much we can say about
                // its type other than it's "Unknown". We could evaluate it as an
                // "object", but that will cause problems given that this type will
                // be wrapped in a "list" below, and lists are invariant.
                if is_type_var_tuple(*type_)
                    && !TypeVarType(*type_)
                        .d()
                        .priv_
                        .borrow()
                        .is_in_union
                        .unwrap_or(false)
                {
                    return UnknownType::create(false).0;
                }

                evaluator.strip_literal_value(*type_)
            })
            .collect();

        let mut entry_type = combine_types(&star_entry_types, None);

        if !unpack_star_entry {
            entry_type = wrap_type_in_list(evaluator, node, entry_type);
        }

        return entry_type;
    }

    // The entry index is past the index of the star entry, so we need
    // to index from the end of the sequence rather than the start.
    let item_index =
        sequence_info.entry_types.len() as i64 - (entry_count as i64 - entry_index as i64);
    assert(
        item_index >= 0 && item_index < sequence_info.entry_types.len() as i64,
        None,
    );

    sequence_info.entry_types[item_index as usize]
}

// analyzer/patternMatching.ts:1889
pub fn assign_type_to_pattern_targets(
    evaluator: &TypeEvaluator,
    type_: P<Type>,
    is_type_incomplete: bool,
    pattern: PatternAtomNode,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    // Further narrow the type based on this pattern.
    let narrowed_type = narrow_type_based_on_pattern(evaluator, type_, pattern, true, node_info);
    let type_result = |type_: P<Type>| {
        P::new_eval(TypeResult {
            is_incomplete: Cell::new(Some(is_type_incomplete)),
            ..TypeResult::new(type_)
        })
    };

    match pattern.node_type {
        ParseNodeType::PatternSequence => {
            let sequence_pattern = PatternSequenceNode::cast(pattern).unwrap();
            let sequence_info: Vec<P<SequencePatternInfo>> =
                get_sequence_pattern_info(evaluator, sequence_pattern, narrowed_type, node_info)
                    .into_iter()
                    .filter(|seq_info| !seq_info.is_definite_no_match)
                    .collect();

            let entries = sequence_pattern.d().entries.borrow().clone();
            for (index, entry) in entries.iter().enumerate() {
                let entry_type = combine_types(
                    &sequence_info
                        .iter()
                        .map(|info| {
                            get_type_of_pattern_sequence_entry(
                                evaluator,
                                pattern,
                                *info,
                                index as i32,
                                sequence_pattern.d().entries.borrow().len() as u32,
                                sequence_pattern.d().star_entry_index.get(),
                                false,
                            )
                        })
                        .collect::<Vec<_>>(),
                    None,
                );

                assign_type_to_pattern_targets(
                    evaluator,
                    entry_type,
                    is_type_incomplete,
                    entry.0,
                    node_info,
                );
            }
        }

        ParseNodeType::PatternAs => {
            let as_pattern = PatternAsNode::cast(pattern).unwrap();
            if let Some(target) = as_pattern.d().target.get() {
                evaluator.assign_type_to_expression(
                    target.0,
                    type_result(narrowed_type),
                    target.0,
                    false,
                    false,
                    None,
                );
            }

            let mut running_narrowed_type = narrowed_type;
            let or_patterns = as_pattern.d().or_patterns.borrow().clone();
            for or_pattern in or_patterns {
                assign_type_to_pattern_targets(
                    evaluator,
                    running_narrowed_type,
                    is_type_incomplete,
                    or_pattern,
                    node_info,
                );

                // OR patterns are evaluated left to right, so we can narrow
                // the type as we go.
                running_narrowed_type = narrow_type_based_on_pattern(
                    evaluator,
                    running_narrowed_type,
                    or_pattern,
                    false,
                    node_info,
                );
            }
        }

        ParseNodeType::PatternCapture => {
            let capture_pattern = PatternCaptureNode::cast(pattern).unwrap();
            let target = capture_pattern.d().target.get();
            if capture_pattern.d().is_wildcard.get() {
                if !is_type_incomplete {
                    if is_unknown(narrowed_type) {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportUnknownVariableType,
                            &LocMessage::wildcard_pattern_type_unknown(),
                            target.0,
                            None,
                        );
                    } else if is_partly_unknown(narrowed_type, 0) {
                        let diag_addendum = DiagnosticAddendum::new();
                        diag_addendum.add_message(LocAddendum::type_of_symbol().format(&[
                            ("name", "_"),
                            (
                                "type",
                                &evaluator.print_type(
                                    narrowed_type,
                                    Some(&PrintTypeOptions {
                                        expand_type_alias: Some(true),
                                        ..Default::default()
                                    }),
                                ),
                            ),
                        ]));
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportUnknownVariableType,
                            &(LocMessage::wildcard_pattern_type_partially_unknown()
                                + &diag_addendum.get_string(
                                    DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                                    DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
                                )),
                            target.0,
                            None,
                        );
                    }
                }
            } else {
                evaluator.assign_type_to_expression(
                    target.0,
                    type_result(narrowed_type),
                    target.0,
                    false,
                    false,
                    None,
                );
            }
        }

        ParseNodeType::PatternMapping => {
            let mapping_pattern = PatternMappingNode::cast(pattern).unwrap();
            let mapping_info = get_mapping_pattern_info(evaluator, narrowed_type, pattern);

            let entries = mapping_pattern.d().entries.borrow().clone();
            for mapping_entry in entries {
                let mut key_types: Vec<P<Type>> = Vec::new();
                let mut value_types: Vec<P<Type>> = Vec::new();
                let key_entry = PatternMappingKeyEntryNode::cast(mapping_entry);
                let expand_entry = PatternMappingExpandEntryNode::cast(mapping_entry);

                for mapping_subtype_info in &mapping_info {
                    if mapping_subtype_info.typed_dict.get().is_some() {
                        if let Some(key_entry) = key_entry {
                            let key_type = narrow_type_based_on_pattern(
                                evaluator,
                                evaluator.get_built_in_object(pattern, "str", None),
                                key_entry.d().key_pattern.get(),
                                true,
                                node_info,
                            );
                            key_types.push(key_type);

                            do_for_each_subtype(
                                key_type,
                                &mut |key_subtype, _, _| {
                                    if is_class_instance(key_subtype)
                                        && ClassType::is_built_in(
                                            ClassType(key_subtype),
                                            Some(&["str".to_string()]),
                                        )
                                        && is_literal_type(ClassType(key_subtype))
                                    {
                                        let td_entries = get_typed_dict_members_for_class(
                                            evaluator,
                                            mapping_subtype_info.typed_dict.get().unwrap(),
                                            false,
                                        );
                                        let key_literal = match &ClassType(key_subtype)
                                            .d()
                                            .priv_
                                            .borrow()
                                            .literal_value
                                        {
                                            Some(LiteralValue::String(value)) => {
                                                Some(value.clone())
                                            }
                                            _ => None,
                                        };
                                        let value_info =
                                            key_literal.as_ref().and_then(|key_literal| {
                                                td_entries
                                                    .known_items
                                                    .borrow()
                                                    .get(key_literal)
                                                    .cloned()
                                            });
                                        value_types.push(match value_info {
                                            Some(value_info) => value_info.value_type,
                                            None => UnknownType::create(false).0,
                                        });
                                    } else {
                                        value_types.push(UnknownType::create(false).0);
                                    }
                                },
                                false,
                            );
                        } else if expand_entry.is_some() {
                            key_types.push(evaluator.get_built_in_object(pattern, "str", None));
                            value_types.push(evaluator.get_object_type());
                        }
                    } else if let Some(dict_type_args) = &mapping_subtype_info.dict_type_args {
                        if let Some(key_entry) = key_entry {
                            let key_type = narrow_type_based_on_pattern(
                                evaluator,
                                dict_type_args.key,
                                key_entry.d().key_pattern.get(),
                                true,
                                node_info,
                            );
                            key_types.push(key_type);
                            value_types.push(narrow_type_based_on_pattern(
                                evaluator,
                                dict_type_args.value,
                                key_entry.d().value_pattern.get(),
                                true,
                                node_info,
                            ));
                        } else if expand_entry.is_some() {
                            key_types.push(dict_type_args.key);
                            value_types.push(dict_type_args.value);
                        }
                    }
                }

                let key_type = combine_types(&key_types, None);
                let value_type = combine_types(&value_types, None);

                if let Some(key_entry) = key_entry {
                    assign_type_to_pattern_targets(
                        evaluator,
                        key_type,
                        is_type_incomplete,
                        key_entry.d().key_pattern.get(),
                        node_info,
                    );
                    assign_type_to_pattern_targets(
                        evaluator,
                        value_type,
                        is_type_incomplete,
                        key_entry.d().value_pattern.get(),
                        node_info,
                    );
                } else if let Some(expand_entry) = expand_entry {
                    let dict_class = evaluator.get_built_in_type(pattern, "dict");
                    let str_type = evaluator.get_built_in_object(pattern, "str", None);
                    let dict_type =
                        if is_instantiable_class(dict_class) && is_class_instance(str_type) {
                            ClassType::clone_as_instance(
                                ClassType::specialize(
                                    ClassType(dict_class),
                                    Some(&[key_type, value_type]),
                                    None,
                                    false,
                                    None,
                                    None,
                                ),
                                true,
                            )
                            .0
                        } else {
                            UnknownType::create(false).0
                        };
                    let target = expand_entry.d().target.get();
                    evaluator.assign_type_to_expression(
                        target.0,
                        type_result(dict_type),
                        target.0,
                        false,
                        false,
                        None,
                    );
                }
            }
        }

        ParseNodeType::PatternClass => {
            let class_pattern = PatternClassNode::cast(pattern).unwrap();
            let pattern_args = class_pattern.d().args.borrow().clone();
            let mut arg_types: Vec<Vec<P<Type>>> =
                pattern_args.iter().map(|_| Vec::new()).collect();

            evaluator.map_subtypes_expand_type_vars(
                narrowed_type,
                None,
                &mut |expanded_subtype, _, _| {
                    if is_class_instance(expanded_subtype) {
                        do_for_each_subtype(
                            narrowed_type,
                            &mut |subject_subtype, _, _| {
                                let concrete_subtype = evaluator.make_top_level_type_vars_concrete(
                                    subject_subtype,
                                    false,
                                    None,
                                );

                                if is_any_or_unknown(concrete_subtype) {
                                    for arg_type in arg_types.iter_mut() {
                                        arg_type.push(concrete_subtype);
                                    }
                                } else if is_class_instance(concrete_subtype) {
                                    // Are there any positional arguments? If so, try to get the mappings for
                                    // these arguments by fetching the __match_args__ symbol from the class.
                                    let mut positional_arg_names: Vec<String> = Vec::new();
                                    if pattern_args.iter().any(|arg| arg.d().name.get().is_none()) {
                                        positional_arg_names = get_positional_match_arg_names(
                                            evaluator,
                                            ClassType::clone_as_instantiable(
                                                ClassType(expanded_subtype),
                                                true,
                                            ),
                                        );
                                    }

                                    for (index, arg) in pattern_args.iter().enumerate() {
                                        let narrowed_arg_type = narrow_type_of_class_pattern_arg(
                                            evaluator,
                                            *arg,
                                            index as i32,
                                            &positional_arg_names,
                                            ClassType::clone_as_instantiable(
                                                ClassType(expanded_subtype),
                                                true,
                                            )
                                            .0,
                                            true,
                                            node_info,
                                        );
                                        arg_types[index].push(narrowed_arg_type);
                                    }
                                }
                            },
                            false,
                        );
                    } else {
                        for arg_type in arg_types.iter_mut() {
                            arg_type.push(UnknownType::create(false).0);
                        }
                    }

                    None
                },
                0,
            );

            for (index, arg) in pattern_args.iter().enumerate() {
                assign_type_to_pattern_targets(
                    evaluator,
                    combine_types(&arg_types[index], None),
                    is_type_incomplete,
                    arg.d().pattern.get().0,
                    node_info,
                );
            }
        }

        // PatternLiteral, PatternValue and Error: nothing to do here.
        _ => {}
    }

    narrowed_type
}

// analyzer/patternMatching.ts:2154
pub(crate) fn wrap_type_in_list(
    evaluator: &TypeEvaluator,
    node: P<ParseNode>,
    type_: P<Type>,
) -> P<Type> {
    if is_never(type_) {
        return type_;
    }

    let list_object_type =
        convert_to_instance(evaluator.get_built_in_object(node, "list", None), true);
    if is_class_instance(list_object_type) {
        // If the type is a union that contains an Any or Unknown, eliminate the other
        // types before wrapping it in a list.
        let type_ = contains_any_or_unknown(type_, false).unwrap_or(type_);

        return ClassType::specialize(
            ClassType(list_object_type),
            Some(&[type_]),
            None,
            false,
            None,
            None,
        )
        .0;
    }

    UnknownType::create(false).0
}

// analyzer/patternMatching.ts:2171
pub fn validate_class_pattern(evaluator: &TypeEvaluator, pattern: PatternClassNode) {
    let class_name = pattern.d().class_name.get();
    let mut expr_type = evaluator
        .get_type_of_expression(class_name, EvalFlags::CallBaseDefaults, None)
        .type_
        .get();

    // If the expression is a type alias or other special form, treat it
    // as the special form rather than the class.
    let special_form = expr_type
        .props
        .borrow()
        .as_ref()
        .and_then(|props| props.special_form);
    if let Some(special_form) = special_form {
        expr_type = special_form.0;
    }

    if is_any_or_unknown(expr_type) {
        return;
    }

    // Check for certain uses of type aliases that generate runtime exceptions.
    let has_type_alias_info = expr_type
        .props
        .borrow()
        .as_ref()
        .is_some_and(|props| props.type_alias_info.is_some());
    if has_type_alias_info
        && is_instantiable_class(expr_type)
        && ClassType(expr_type).d().priv_.borrow().type_args.is_some()
        && ClassType(expr_type)
            .d()
            .priv_
            .borrow()
            .is_type_arg_explicit
            .unwrap_or(false)
    {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocMessage::class_pattern_type_alias()
                .format(&[("type", &evaluator.print_type(expr_type, None))]),
            class_name,
            None,
        );
    } else if !is_instantiable_class(expr_type) {
        if !is_never(expr_type) {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocAddendum::type_not_class()
                    .format(&[("type", &evaluator.print_type(expr_type, None))]),
                class_name,
                None,
            );
        }
    } else if ClassType::is_new_type_class(ClassType(expr_type)) {
        evaluator.add_diagnostic(
            DiagnosticRule::reportGeneralTypeIssues,
            &LocMessage::class_pattern_new_type()
                .format(&[("type", &evaluator.print_type(expr_type, None))]),
            class_name,
            None,
        );
    } else {
        let expr_class = ClassType(expr_type);
        let is_built_in = is_class_special_case_for_class_pattern(expr_class);
        let pattern_args = pattern.d().args.borrow().clone();

        // If it's a special-case builtin class, only positional arguments are allowed.
        if is_built_in {
            if pattern_args.len() == 1 {
                if let Some(name) = pattern_args[0].d().name.get() {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::class_pattern_built_in_arg_positional(),
                        name.0,
                        None,
                    );
                }
            }
        }

        // Emits an error if the supplied number of positional patterns is less than
        // expected for the given subject type.
        let mut positional_pattern_count: i32 = pattern_args
            .iter()
            .position(|arg| arg.d().name.get().is_some())
            .map_or(-1, |index| index as i32);
        if positional_pattern_count < 0 {
            positional_pattern_count = pattern_args.len() as i32;
        }

        let mut expected_pattern_count: i32 = 1;
        if !is_built_in {
            let mut positional_arg_names: Vec<String> = Vec::new();
            if pattern_args.iter().any(|arg| arg.d().name.get().is_none()) {
                positional_arg_names = get_positional_match_arg_names(evaluator, expr_class);
            }

            expected_pattern_count = positional_arg_names.len() as i32;
        }

        if positional_pattern_count > expected_pattern_count {
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &LocMessage::class_pattern_positional_arg_count().format(&[
                    ("type", &expr_class.d().shared.get().name),
                    ("expected", &expected_pattern_count.to_string()),
                    ("received", &positional_pattern_count.to_string()),
                ]),
                pattern_args[expected_pattern_count as usize].0,
                None,
            );
        }
    }
}

// analyzer/patternMatching.ts:2258
pub fn get_pattern_subtype_narrowing_callback(
    evaluator: &TypeEvaluator,
    reference: CodeFlowReferenceExpressionNode,
    subject_expression: ExpressionNode,
) -> Option<PatternSubtypeNarrowingCallback> {
    let evaluator_handle: P<TypeEvaluator> = *evaluator.evaluator_interface.get().unwrap();
    let is_built_in = |class_type: ClassType, name: &str| {
        ClassType::is_built_in(class_type, Some(&[name.to_string()]))
    };

    // Look for a subject expression of the form <reference>[<literal>] where
    // <literal> is either a str (for TypedDict discrimination) or an int
    // (for tuple discrimination).
    if let Some(index_node) = IndexNode::cast(subject_expression) {
        let items = index_node.d().items.borrow().clone();
        if items.len() == 1
            && !index_node.d().trailing_comma.get()
            && items[0].d().arg_category.get() == ArgCategory::Simple
            && is_matching_expression(reference, index_node.d().left_expr.get(), None)
        {
            let index_type_result = evaluator.get_type_of_expression(
                items[0].d().value_expr.get(),
                EvalFlags::None,
                None,
            );
            let index_type = index_type_result.type_.get();

            if is_class_instance(index_type) && is_literal_type(ClassType(index_type)) {
                let index_class = ClassType(index_type);
                if ClassType::is_built_in(
                    index_class,
                    Some(&["int".to_string(), "str".to_string()]),
                ) {
                    let unnarrowed_reference_type_result = evaluator.get_type_of_expression(
                        index_node.d().left_expr.get(),
                        EvalFlags::CallBaseDefaults,
                        None,
                    );
                    let unnarrowed_reference_type = unnarrowed_reference_type_result.type_.get();

                    return Some(Rc::new(move |narrowed_subject_type: P<Type>| {
                        let evaluator = evaluator_handle.get();
                        let mut can_narrow = true;
                        let mut types_to_combine: Vec<P<Type>> = Vec::new();

                        do_for_each_subtype(
                            narrowed_subject_type,
                            &mut |subtype, _, _| {
                                let subtype = evaluator
                                    .make_top_level_type_vars_concrete(subtype, false, None);

                                if is_class_instance(subtype)
                                    && ClassType(subtype)
                                        .d()
                                        .priv_
                                        .borrow()
                                        .literal_value
                                        .is_some()
                                {
                                    if is_built_in(index_class, "str") {
                                        types_to_combine.push(
                                            narrow_type_for_discriminated_dict_entry_comparison(
                                                evaluator,
                                                unnarrowed_reference_type,
                                                index_class,
                                                subtype,
                                                true,
                                            ),
                                        );
                                    } else {
                                        types_to_combine.push(
                                            narrow_type_for_discriminated_tuple_comparison(
                                                evaluator,
                                                unnarrowed_reference_type,
                                                index_class,
                                                subtype,
                                                true,
                                            ),
                                        );
                                    }
                                } else if !is_never(subtype) {
                                    // We don't know how to narrow in this case.
                                    can_narrow = false;
                                }
                            },
                            false,
                        );

                        if !can_narrow {
                            return None;
                        }

                        // `indexTypeResult.isIncomplete || unnarrowedReferenceTypeResult.isIncomplete`.
                        let index_type_is_incomplete = index_type_result.is_incomplete.get();
                        Some(P::new_eval(TypeResult {
                            is_incomplete: Cell::new(if index_type_is_incomplete == Some(true) {
                                index_type_is_incomplete
                            } else {
                                unnarrowed_reference_type_result.is_incomplete.get()
                            }),
                            ..TypeResult::new(combine_types(&types_to_combine, None))
                        }))
                    }));
                }
            }
        }
    }

    // Look for a subject expression that contains the reference
    // expression as an entry in a tuple.
    if let Some(tuple_node) = TupleNode::cast(subject_expression) {
        let items = tuple_node.d().items.borrow().clone();
        let matching_entry_index = items
            .iter()
            .position(|expr| is_matching_expression(reference, *expr, None));
        if let Some(matching_entry_index) = matching_entry_index {
            let type_result = evaluator.get_type_of_expression(
                items[matching_entry_index],
                EvalFlags::None,
                None,
            );

            return Some(Rc::new(move |narrowed_subject_type: P<Type>| {
                let mut can_narrow = true;
                let mut narrowed_subtypes: Vec<P<Type>> = Vec::new();

                do_for_each_subtype(
                    narrowed_subject_type,
                    &mut |subtype, _, _| {
                        let tuple_type_args = if is_class_instance(subtype)
                            && is_built_in(ClassType(subtype), "tuple")
                        {
                            ClassType(subtype)
                                .d()
                                .priv_
                                .borrow()
                                .tuple_type_args
                                .map(|tuple_type_args| tuple_type_args.borrow().clone())
                        } else {
                            None
                        };
                        if let Some(tuple_type_args) = tuple_type_args.filter(|tuple_type_args| {
                            matching_entry_index < tuple_type_args.len()
                                && tuple_type_args.iter().all(|e| !e.is_unbounded)
                        }) {
                            narrowed_subtypes.push(tuple_type_args[matching_entry_index].type_);
                        } else if is_never(narrowed_subject_type) {
                            narrowed_subtypes.push(narrowed_subject_type);
                        } else {
                            can_narrow = false;
                        }
                    },
                    false,
                );

                if can_narrow {
                    Some(P::new_eval(TypeResult {
                        is_incomplete: Cell::new(type_result.is_incomplete.get()),
                        ..TypeResult::new(combine_types(&narrowed_subtypes, None))
                    }))
                } else {
                    None
                }
            }));
        }
    }

    // Look for a subject expression of the form "a.b" where "b" is an attribute
    // that is annotated with a literal type.
    if let Some(member_access_node) = MemberAccessNode::cast(subject_expression) {
        if is_matching_expression(reference, member_access_node.d().left_expr.get(), None) {
            let unnarrowed_reference_type_result = evaluator.get_type_of_expression(
                member_access_node.d().left_expr.get(),
                EvalFlags::CallBaseDefaults,
                None,
            );
            let unnarrowed_reference_type = unnarrowed_reference_type_result.type_.get();

            return Some(Rc::new(move |narrowed_subject_type: P<Type>| {
                let evaluator = evaluator_handle.get();
                if is_never(narrowed_subject_type) {
                    return Some(P::new_eval(TypeResult::new(NeverType::create_never().0)));
                }

                if !is_literal_type_or_union(narrowed_subject_type, false) {
                    return None;
                }

                let result_type = map_subtypes(
                    narrowed_subject_type,
                    &mut |literal_subtype| {
                        assert(
                            is_class_instance(literal_subtype)
                                && ClassType(literal_subtype)
                                    .d()
                                    .priv_
                                    .borrow()
                                    .literal_value
                                    .is_some(),
                            None,
                        );

                        Some(narrow_type_for_discriminated_literal_field_comparison(
                            evaluator,
                            unnarrowed_reference_type,
                            &member_access_node.d().member.get().d().value,
                            ClassType(literal_subtype),
                            true,
                        ))
                    },
                    None,
                );

                Some(P::new_eval(TypeResult::new(result_type)))
            }));
        }
    }

    None
}

// analyzer/patternMatching.ts:2408
pub(crate) fn report_unnecessary_pattern(
    evaluator: &TypeEvaluator,
    pattern: PatternAtomNode,
    subject_type: P<Type>,
) {
    // If this is a simple wildcard pattern, exempt it from this diagnostic.
    if let Some(as_pattern) = PatternAsNode::cast(pattern) {
        let or_patterns = as_pattern.d().or_patterns.borrow().clone();
        if or_patterns.len() == 1
            && PatternCaptureNode::cast(or_patterns[0])
                .is_some_and(|capture| capture.d().is_wildcard.get())
        {
            return;
        }
    }

    evaluator.add_diagnostic(
        DiagnosticRule::reportUnnecessaryComparison,
        &LocMessage::pattern_never_matches()
            .format(&[("type", &evaluator.print_type(subject_type, None))]),
        pattern,
        None,
    );
}

// Inline object type at MappingPatternInfo.dictTypeArgs.
#[derive(Clone)]
pub struct MappingPatternInfoDictTypeArgs {
    pub key: P<Type>,
    pub value: P<Type>,
}
